local ButterChurnMaker = {}
local PRODUCTS = {
    iron_butter_churn = { name = "Železna kada za maslo", ironCost = 1, woodCost = 3, leatherCost = 2, time = 5, cost = 150, prestige = 3, happiness = 2, description = "Železna kada za stepenje masla." },
    bronze_butter_churn = { name = "Bronasta kada za maslo", bronzeCost = 1, ironCost = 1, woodCost = 3, leatherCost = 2, time = 7, cost = 360, prestige = 5, happiness = 3, description = "Bronasta kada za mlekarno." },
    silver_butter_churn = { name = "Srebrna kada za maslo", silverCost = 1, bronzeCost = 1, ironCost = 1, woodCost = 3, leatherCost = 2, time = 11, cost = 870, prestige = 10, happiness = 4, description = "Srebrna kada za plemiške kuharje." },
    gilded_butter_churn = { name = "Pozlačena kada za maslo", goldCost = 1, silverCost = 1, bronzeCost = 1, woodCost = 3, leatherCost = 2, time = 15, cost = 1850, prestige = 19, happiness = 5, description = "Pozlačena kada za dvorne kuharje." },
    jewel_set_butter_churn = { name = "Draguljasta kada za maslo", goldCost = 2, silverCost = 1, jewelCost = 1, bronzeCost = 1, woodCost = 3, leatherCost = 2, time = 19, cost = 3980, prestige = 35, happiness = 7, description = "Draguljasta kada za kraljeve kuharje." },
    royal_sovereign_butter_churn = { name = "Kraljevski suverena kada za maslo", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 4, leatherCost = 2, time = 26, cost = 8500, prestige = 68, happiness = 13, description = "Suverena kada z biseri za krono." },
}
local BUILDINGS = {
    butterchurn_workshop = { name = "Kadna delavnica", cost = { gold = 310, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    butterchurn_house = { name = "Kadna hiša", cost = { gold = 1150, wood = 365, stone = 265, silver = 7, iron = 7 }, upkeep = 24, qualityBonus = 18 },
    master_butterchurn_atelier = { name = "Mojstrski kadni atelje", cost = { gold = 2920, wood = 425, stone = 510, silver = 34, gold = 7 }, upkeep = 69, qualityBonus = 30 },
    sovereign_butterchurn_palace = { name = "Suverena kadna palača", cost = { gold = 12650, wood = 650, stone = 815, gold = 81, jewel = 18 }, upkeep = 248, qualityBonus = 55, prestigeBonus = 50 },
}
ButterChurnMaker.ironStock = 10; ButterChurnMaker.bronzeStock = 8; ButterChurnMaker.woodStock = 18; ButterChurnMaker.leatherStock = 12; ButterChurnMaker.silverStock = 8; ButterChurnMaker.goldStock = 6; ButterChurnMaker.jewelStock = 4; ButterChurnMaker.pearlStock = 4
ButterChurnMaker.productStock = {}; ButterChurnMaker.buildings = {}; ButterChurnMaker.maker = nil; ButterChurnMaker.activeMaking = {}; ButterChurnMaker.totalProducts = 0; ButterChurnMaker.dayTimer = 0
function ButterChurnMaker.init() ButterChurnMaker.ironStock=10; ButterChurnMaker.bronzeStock=8; ButterChurnMaker.woodStock=18; ButterChurnMaker.leatherStock=12; ButterChurnMaker.silverStock=8; ButterChurnMaker.goldStock=6; ButterChurnMaker.jewelStock=4; ButterChurnMaker.pearlStock=4; ButterChurnMaker.productStock={}; ButterChurnMaker.buildings={}; ButterChurnMaker.maker=nil; ButterChurnMaker.activeMaking={}; ButterChurnMaker.totalProducts=0; ButterChurnMaker.dayTimer=0; print("[ButterChurnMaker] Royal Butter Churn Maker System initialized (6 products, 4 buildings)") end
function ButterChurnMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ButterChurnMaker.maker={name=n or ("Kadar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kadar najet: %s (spretnost: %d)",ButterChurnMaker.maker.name,s),"success") end; return true end
function ButterChurnMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ButterChurnMaker.build(id) local ok,e=ButterChurnMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ButterChurnMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ButterChurnMaker.getQualityBonus() local b=0; for _,bd in ipairs(ButterChurnMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ButterChurnMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and ButterChurnMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and ButterChurnMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and ButterChurnMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and ButterChurnMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and ButterChurnMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ButterChurnMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ButterChurnMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ButterChurnMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ButterChurnMaker.buildings==0 then return false,"Potrebna kadna delavnica" end; if not ButterChurnMaker.maker then return false,"Potreben kadar" end; return true end
function ButterChurnMaker.make(pt,qty) qty=qty or 1; local ok,e=ButterChurnMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then ButterChurnMaker.ironStock=ButterChurnMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then ButterChurnMaker.bronzeStock=ButterChurnMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then ButterChurnMaker.woodStock=ButterChurnMaker.woodStock-d.woodCost*qty end; if d.leatherCost then ButterChurnMaker.leatherStock=ButterChurnMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then ButterChurnMaker.silverStock=ButterChurnMaker.silverStock-d.silverCost*qty end; if d.goldCost then ButterChurnMaker.goldStock=ButterChurnMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ButterChurnMaker.jewelStock=ButterChurnMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ButterChurnMaker.pearlStock=ButterChurnMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ButterChurnMaker.maker then t=math.max(1,t-math.floor(ButterChurnMaker.maker.skill/13)) end; table.insert(ButterChurnMaker.activeMaking,{id="butterchurn_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ButterChurnMaker.completeMaking(m) local q=1.0+(ButterChurnMaker.getQualityBonus()/100); if ButterChurnMaker.maker then q=q+(ButterChurnMaker.maker.skill/140) end; q=math.min(2.5,q); ButterChurnMaker.productStock[m.productType]=(ButterChurnMaker.productStock[m.productType] or 0)+m.quantity; ButterChurnMaker.totalProducts=ButterChurnMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ButterChurnMaker.maker then ButterChurnMaker.maker.itemsMade=ButterChurnMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ButterChurnMaker.maker.skill=math.min(100,ButterChurnMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kada izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"butterchurn.completed",{productName=m.productName,prestige=m.prestige,happiness:m.happiness}) end end
function ButterChurnMaker.update(dt) if not _G.state then return end; ButterChurnMaker.dayTimer=ButterChurnMaker.dayTimer+dt; if ButterChurnMaker.dayTimer>=30 then ButterChurnMaker.dayTimer=0; for i=#ButterChurnMaker.activeMaking,1,-1 do local m=ButterChurnMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ButterChurnMaker.completeMaking(m); table.remove(ButterChurnMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ButterChurnMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ButterChurnMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ButterChurnMaker.getStats() return {ironStock=ButterChurnMaker.ironStock,bronzeStock=ButterChurnMaker.bronzeStock,woodStock=ButterChurnMaker.woodStock,leatherStock=ButterChurnMaker.leatherStock,silverStock=ButterChurnMaker.silverStock,goldStock=ButterChurnMaker.goldStock,jewelStock=ButterChurnMaker.jewelStock,pearlStock=ButterChurnMaker.pearlStock,productStock=ButterChurnMaker.productStock,numBuildings=#ButterChurnMaker.buildings,hasMaker=ButterChurnMaker.maker~=nil,makerName=ButterChurnMaker.maker and ButterChurnMaker.maker.name or "—",makerSkill=ButterChurnMaker.maker and ButterChurnMaker.maker.skill or 0,activeMaking=#ButterChurnMaker.activeMaking,totalProducts=ButterChurnMaker.totalProducts} end
return ButterChurnMaker
